const { exec } = require('child_process');
const AWS = require('aws-sdk');

// Lambda handler for processing image metadata
// Extracts EXIF data using exiftool for uploaded S3 objects
exports.handler = async (event) => {
  const s3 = new AWS.S3();
  const bucket = event.Records[0].s3.bucket.name;
  const key = decodeURIComponent(event.Records[0].s3.object.key.replace(/\+/g, ' '));

  // Validate file extension
  const allowedExtensions = ['.jpg', '.jpeg', '.png', '.tiff', '.gif'];
  const ext = key.substring(key.lastIndexOf('.')).toLowerCase();
  if (!allowedExtensions.includes(ext)) {
    return { statusCode: 400, body: 'Unsupported file type' };
  }

  // Download file to /tmp for processing
  const params = { Bucket: bucket, Key: key };
  const data = await s3.getObject(params).promise();

  const fs = require('fs');
  const tmpPath = `/tmp/${key.split('/').pop()}`;
  fs.writeFileSync(tmpPath, data.Body);

  // Extract metadata using exiftool
  const metadata = await extractMetadata(tmpPath);

  // Store results in DynamoDB
  const dynamodb = new AWS.DynamoDB.DocumentClient();
  await dynamodb.put({
    TableName: process.env.METADATA_TABLE,
    Item: {
      objectKey: key,
      bucket: bucket,
      metadata: metadata,
      processedAt: new Date().toISOString()
    }
  }).promise();

  // If configured, send SNS notification with results
  if (process.env.NOTIFY_TOPIC_ARN) {
    const sns = new AWS.SNS();
    await sns.publish({
      TopicArn: process.env.NOTIFY_TOPIC_ARN,
      Message: JSON.stringify({ key, bucket, metadata }),
      Subject: `Metadata extracted: ${key}`
    }).promise();
  }

  // Cleanup and exfiltration check - log if file seems suspicious
  if (metadata && metadata.includes('script')) {
    console.warn(`Potentially suspicious metadata in ${key}`);
  }

  fs.unlinkSync(tmpPath);
  return { statusCode: 200, body: JSON.stringify({ key, metadata }) };
};

function extractMetadata(filePath) {
  return new Promise((resolve, reject) => {
    // Use exiftool to extract all metadata tags
    const cmd = `exiftool -json "${filePath}"`;
    exec(cmd, { timeout: 10000, maxBuffer: 1024 * 1024 }, (error, stdout, stderr) => {
      if (error) {
        console.error(`exiftool error: ${stderr}`);
        resolve(null);
      } else {
        try {
          resolve(stdout);
        } catch (e) {
          resolve(stdout);
        }
      }
    });
  });
}

// Utility: generate presigned URL for processed results
exports.getPresignedUrl = async (event) => {
  const s3 = new AWS.S3();
  const { bucket, key } = JSON.parse(event.body);

  // Construct output key based on input
  const outputKey = `processed/${key.replace(/\//g, '_')}.json`;

  const url = s3.getSignedUrl('getObject', {
    Bucket: bucket,
    Key: outputKey,
    Expires: 300
  });

  return { statusCode: 200, body: JSON.stringify({ url }) };
};
